'use strict';
const X=window.AOLCatalog,C=window.AOLCore,D=window.AOL_SEED,E=C.esc,$=s=>document.querySelector(s);
let storage;try{storage=window.localStorage}catch{storage={getItem(){throw Error('blocked')},setItem(){throw Error('blocked')}}}
try{const rows=JSON.parse(storage.getItem('aol12_public_catalog')||'[]');for(const p of rows){if(!p?.place_id)continue;const i=D.places.findIndex(x=>x.place_id===p.place_id);if(i>=0)D.places[i]=p;else D.places.push(p)}}catch{}
const loaded=C.read(storage,D.places.map(p=>p.place_id));let db=loaded.data,storageBlocked=!!loaded.blocked;
let filters={q:'',category:'전체',district:'전체',free:false,indoor:false},showCount=18,globalResults=[],globalQuery='',globalBusy=false,globalError='',searchSeq=0,toastTimer,installPrompt=null;
const allPlaces=()=>[...D.places.filter(p=>p.is_published!==false),...db.candidates];const place=id=>D.places.find(p=>p.place_id===id)||db.candidates.find(p=>p.place_id===id);const route=id=>db.routes.find(r=>r.id===id);
const navItems=[['home','⌂','홈'],['explore','⌕','발견'],['map','◎','지도'],['saved','♡','저장'],['my','◉','마이']];
function commit(next){if(storageBlocked){toast('기존 데이터 읽기 오류가 있습니다. 설정에서 백업 복원 또는 초기화가 필요합니다.');return false}if(!C.write(storage,next)){toast('기기에 저장하지 못했습니다. 저장 공간·브라우저 권한을 확인하세요.');return false}db=next;if(window.AOLCloud)window.dispatchEvent(new CustomEvent("aol:changed"));return true}
function change(fn){const next=JSON.parse(JSON.stringify(db));fn(next);return commit(next)}
function toast(text){const el=$('#toast');el.textContent=text;el.classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('visible'),4200)}
function go(path){if(location.hash==='#'+path)render();else location.hash=path}
function pagePath(){try{return decodeURIComponent(location.hash.slice(1)||'home').split('/')}catch{return ['home']}}
function badge(p){const f=C.freshness(p);return `<span class="pill ${f.tone}">${E(f.label)}</span>`}
function category(p){return ({'Media Facade':'미디어파사드','Media Art':'미디어아트','Immersive':'몰입형 전시','Light Art':'라이트아트','Architecture':'건축','Global':'글로벌 프로젝트','Architectural Lighting':'건축조명','Nightscape':'야간경관','Public Art':'공공미술','Exhibition':'전시·페스티벌'})[p.primary_category]||p.primary_category}
function official(p){return C.safeURL(p.verification_source_1||p.website||p.source_url)}
function link(url,text,cls='source-link'){const u=C.safeURL(url);return u?`<a class="${cls}" href="${E(u)}" target="_blank" rel="noopener noreferrer">${E(text)} ↗</a>`:''}
function art(p,extra=''){const m=mediaFor(p)[0];return `<div class="card-art ${extra}">${m?`<img src="${E(mediaURL(m))}" alt="${E(p.name_kr)}" loading="lazy" decoding="async" data-place-photo data-original="${E(C.safeURL(m.original_file_url))}"><span class="image-credit">${E(m.creator||'')} · ${E(m.license_code||'')} · 출처는 상세페이지</span>`:`<div class="photo-pending"><img src="./assets/symbol.svg" alt=""><span>사진 준비 중</span><small>권리가 확인된 실제 사진만 표시합니다.</small></div>`}</div>`}
function card(p){return `<article class="place-card"><a href="#place/${E(p.place_id)}" aria-label="${E(p.name_kr)} 상세">${art(p)}</a><button class="save-button ${db.saved.includes(p.place_id)?'saved':''}" data-save="${E(p.place_id)}" aria-label="${E(p.name_kr)} ${db.saved.includes(p.place_id)?'저장 해제':'저장'}" aria-pressed="${db.saved.includes(p.place_id)}">${db.saved.includes(p.place_id)?'♥':'♡'}</button><div class="card-body"><div class="card-meta">${E(category(p))} <span aria-hidden="true">/</span> ${E(p.district||'세계')}</div><a href="#place/${E(p.place_id)}"><h3>${E(p.name_kr)}</h3></a><div class="card-meta">${p.free===true?'무료로 수록':p.free===false?'유료·조건부로 수록':'요금 미확인'}</div><div class="card-bottom">${badge(p)}<button class="button subtle small" data-add-route="${E(p.place_id)}">＋ 코스</button></div></div></article>`}
function row(p,extra=''){return `<div class="list-row"><span class="stop-number">↗</span><div class="row-main"><a href="#place/${E(p.place_id)}"><h3>${E(p.name_kr)}</h3></a><p>${E(extra||`${category(p)} · ${p.district||'세계 검색'}`)}</p></div><button class="button subtle small" data-add-route="${E(p.place_id)}">＋ 코스</button></div>`}
function empty(title,body,action=''){return `<div class="empty"><h3>${E(title)}</h3><p>${E(body)}</p>${action}</div>`}
function heading(eyebrow,title,sub=''){return `<div class="eyebrow">${eyebrow}</div><h1>${title}</h1>${sub?`<p class="muted">${sub}</p>`:''}`}
function home(){const ps=allPlaces().filter(p=>p.origin!=='wikidata'),now=ps.filter(p=>X.available(p,C.today())),curated=ps.filter(p=>p.MVP_priority==='A'||p.mvp_priority==='A').slice(0,6),regions=[...new Set(ps.map(p=>X.region(p).city).filter(Boolean))],themes=D.curations.filter(c=>D.curation_places.some(x=>x.curation_id===c.curation_id&&ps.some(p=>p.place_id===x.place_id))),updates=ps.filter(p=>p.updated_at&&p.publication_status==='approved').sort((a,b)=>b.updated_at.localeCompare(a.updated_at)).slice(0,4),featured=ps.find(p=>mediaFor(p).length);return `<section class="discover-hero"><div class="hero-copy"><div class="eyebrow">ARCHITECTURE OF LIGHT</div><h1>빛이 머무는 공간,<br>나의 다음 발견.</h1><p>건축과 미디어아트를 찾아보고<br>나만의 답사와 기록으로 이어가세요.</p><form id="homeSearch" class="hero-search"><input name="q" aria-label="통합 검색" placeholder="장소, 도시, 작가를 검색하세요"><button class="button">검색</button></form><div class="actions"><a class="hero-link" href="#explore">프로젝트 탐색 →</a><a class="hero-link" href="#map">지도에서 보기 ↗</a></div></div><div class="hero-feature">${featured?art(featured,'hero-photo'):'<img src="./assets/symbol.svg" alt="빛의 건축 심볼"><span>빛과 공간을 기록하는 아카이브<br><small>대표 프로젝트 사진은 권리 확인 후 공개합니다.</small></span>'}</div></section><section class="category-grid" aria-label="프로젝트 유형">${X.categories.map(([key,name,icon])=>{const n=X.search(ps,{category:key},C.today()).length;return `<button class="category-tile" data-discover-category="${key}" ${!n?'disabled':''}><span aria-hidden="true">${icon}</span><b>${name}</b><small>${n?n+'개 프로젝트':'자료 준비 중'}</small></button>`}).join('')}</section>${now.length?sectionCards('지금 볼 수 있는 빛의 공간','공식 운영정보의 확인 유효기간 내에 있는 프로젝트',now.slice(0,6)):''}${ps.some(p=>mediaFor(p).length)?sectionCards('사진으로 살펴보는 공간','출처를 확인한 과거 장소 사진 · 상세페이지에서 촬영일 확인',ps.filter(p=>mediaFor(p).length).slice(0,6)):''}${sectionCards('빛의 공간, 여기서 시작하세요','기존 아카이브의 A 우선순위 수록 프로젝트 · 인기 순위가 아닙니다.',curated)}<section><div class="section-head"><div><p class="eyebrow">BY LOCATION</p><h2>어디의 빛을 만나볼까요?</h2><small>현재 자료가 등록된 지역부터 살펴보세요.</small></div></div><div class="region-grid">${regions.map(city=>`<button class="region-card" data-city-link="${E(city)}"><span>${E(city)}</span><small>${ps.filter(p=>X.region(p).city===city).length}개 프로젝트 →</small></button>`).join('')}<a class="region-card" href="#explore"><span>세계 프로젝트 찾기</span><small>외부 데이터베이스 후보 검색 ↗</small></a></div></section>${themes.length?`<section><div class="section-head"><div><p class="eyebrow">CURATED JOURNEYS</p><h2>하나의 시선, 여러 공간</h2></div><a href="#routes" class="text-link">전체 큐레이션 →</a></div><div class="collection-grid">${themes.slice(0,4).map(collection).join('')}</div></section>`:''}${updates.length?sectionCards('새로 확인한 프로젝트','공개 승인된 프로젝트의 최종 업데이트 기준',updates):''}${articles().length?`<section><div class="section-head"><h2>빛의 건축 읽기</h2><a href="#magazine">아카이브 →</a></div>${magazineCards()}</section>`:''}<div class="archive-note"><b>출처와 함께 보는 아카이브</b><p>운영시간·일정·이미지 권리의 확인 상태를 함께 표시합니다. 방문 전에는 프로젝트의 공식 안내를 확인하세요.</p><a href="#settings">데이터 상태 확인 →</a></div>`}
function collection(c,i){const n=D.curation_places.filter(x=>x.curation_id===c.curation_id&&place(x.place_id)).length;return `<a class="collection" href="#curation/${E(c.curation_id)}"><span class="collection-number">0${i+1} ↝</span><h3>${E(c.title)}</h3><p>${E(c.subtitle||c.description)}</p><span class="pill">${n}곳 · 원본 코스</span></a>`}
function filterHTML(){const ps=allPlaces(),countries=[...new Set(ps.map(p=>X.region(p).country).filter(Boolean))],cities=[...new Set(ps.filter(p=>!filters.country||X.region(p).country===filters.country).map(p=>X.region(p).city).filter(Boolean))],years=[...new Set(ps.map(p=>String(p.project_year||p.program_start?.slice(0,4)||'')).filter(Boolean))].sort().reverse();const opts=(xs,current)=>'<option value="">전체</option>'+xs.map(x=>`<option value="${E(x)}" ${x===current?'selected':''}>${E(x)}</option>`).join('');return `<div class="filterbar"><input class="search-field" id="placeSearch" aria-label="프로젝트 통합 검색" value="${E(filters.q)}" placeholder="작품·장소·국가·도시·작가 검색"><button class="button subtle" data-reset-filter>초기화</button></div><div class="chips"><button class="chip ${filters.category==='전체'?'active':''}" data-category="전체">전체</button>${[...new Set(ps.map(p=>p.primary_category))].filter(Boolean).map(key=>`<button class="chip ${filters.category===key?'active':''}" data-category="${E(key)}">${E(category({primary_category:key}))}</button>`).join('')}</div><details class="advanced-filters"><summary>지역·일정·유형 상세 필터${Object.keys(filters).filter(k=>['country','city','state','kind','year'].includes(k)&&filters[k]).length?' · 적용 중':''}</summary><div class="advanced-grid"><label>국가<select data-search-filter="country">${opts(countries,filters.country)}</select></label><label>도시<select data-search-filter="city">${opts(cities,filters.city)}</select></label><label>일정 상태<select data-search-filter="state"><option value="">전체</option>${[['ongoing','수록 일정상 진행 중'],['upcoming','개막 예정'],['ended','종료'],['permanent','상설']].map(([v,t])=>`<option value="${v}" ${filters.state===v?'selected':''} ${ps.some(p=>X.status(p,C.today())===v)?'':'disabled'}>${t}</option>`).join('')}</select></label><label>콘텐츠 구분<select data-search-filter="kind"><option value="">전체</option>${[['permanent','상설'],['temporary','기간형']].map(([v,t])=>`<option value="${v}" ${filters.kind===v?'selected':''} ${ps.some(p=>p.content_type===v)?'':'disabled'}>${t}</option>`).join('')}</select></label><label>제작·개최 연도<select data-search-filter="year" ${years.length?'':'disabled'}>${opts(years,filters.year)}</select></label><label>정렬<select data-search-filter="sort"><option value="relevance">검색 관련도</option><option value="newest" ${filters.sort==='newest'?'selected':''} ${ps.some(p=>p.created_at)?'':'disabled'}>최신 등록순</option><option value="updated" ${filters.sort==='updated'?'selected':''} ${ps.some(p=>p.updated_at)?'':'disabled'}>최신 수정순</option></select></label></div><div class="chips"><button class="chip ${filters.free?'active':''}" data-filter-toggle="free">무료로 수록</button><button class="chip ${filters.indoor?'active':''}" data-filter-toggle="indoor">실내</button></div></details>`}
function resultsHTML(){const ps=X.search(allPlaces(),filters,C.today());return `<div class="result-meta" role="status">${ps.length}개 프로젝트 · ${Math.min(ps.length,showCount)}개 표시</div>${ps.length?`<div class="grid">${ps.slice(0,showCount).map(card).join('')}</div>${ps.length>showCount?'<button class="button subtle" data-more>더 보기</button>':''}`:empty('검색 조건에 맞는 프로젝트가 없습니다.','다른 검색어나 지역을 선택하세요.')} `}
function explore(){return heading('EXPLORE THE CITY','빛의 장소 탐색','장소를 찾고, 출처를 확인하고, 다음 답사에 담으세요.')+'<div class="actions"><a class="button subtle" href="#map">지도 보기 ↗</a><a class="button subtle" href="#calendar">프로그램 일정</a></div>'+filterHTML()+`<div id="placeResults">${resultsHTML()}</div><div class="section-head"><div><h2>서울 너머의 빛</h2><small>Wikidata 공개 검색 · 결과는 검토되지 않은 후보입니다.</small></div></div><div class="filterbar"><input id="globalSearch" class="search-field" value="${E(globalQuery)}" placeholder="예: teamLab Borderless" aria-label="세계 장소 검색"><button class="button" id="globalSearchButton" ${globalBusy?'disabled':''}>${globalBusy?'검색 중…':'세계 검색 ↗'}</button></div><div id="globalResults">${globalHTML()}</div>`}
function globalHTML(){if(globalBusy)return '<p class="loading" role="status">외부 공개 데이터를 검색하고 있습니다…</p>';if(globalError)return `<div class="notice warning" role="alert">${E(globalError)} <button class="button subtle small" data-retry-global>다시 시도</button></div>`;return globalResults.map(x=>`<div class="list-row"><div class="row-main"><h3>${E(x.name_kr)}</h3><p>${E(x.short_description)}</p>${link(x.source_url,'Wikidata 출처')}</div><button class="button subtle small" data-global-save="${E(x.place_id)}">${db.candidates.some(c=>c.place_id===x.place_id)?'저장됨':'＋ 저장'}</button></div>`).join('')||'<p class="muted">검색 버튼을 누를 때만 외부 서비스에 검색어를 보냅니다.</p>'}
function detailLegacy(p){if(!p)return notFound();const f=C.freshness(p),vis=db.visits.filter(v=>v.placeId===p.place_id),src=D.sources.filter(s=>s.place_id===p.place_id);const mapURL='https://www.google.com/maps/search/?api=1&query='+encodeURIComponent(C.coords(p)?C.coords(p).join(','):p.address||p.name_kr);return `<a class="text-link" href="#explore">← 장소 탐색</a><div style="margin-top:24px">${heading(E(category(p))+' / '+E(p.district||'GLOBAL'),E(p.name_kr),E(p.name_en||''))}</div><div class="actions">${badge(p)}<button class="button subtle small" data-save="${E(p.place_id)}">${db.saved.includes(p.place_id)?'♥ 저장됨':'♡ 저장'}</button><button class="button subtle small" data-share="${E(p.place_id)}">링크 복사</button></div><div class="detail-layout"><div>${art(p,'detail-art')}<p class="detail-description">${E(p.short_description)}</p>${p.why_it_matters?`<p class="quote">${E(p.why_it_matters)}</p>`:''}<section class="panel"><h2>빛의 건축 해설</h2><p>${E(p.expert_description||p.description||'세계 검색 결과는 아직 에디토리얼 검토 전입니다.')}</p></section><section class="panel"><h2>이미지와 출처</h2><p class="muted">검토한 장소 사진과 촬영일·원본 출처를 표시합니다. 과거 외관 사진은 현재 전시나 상영 상태를 뜻하지 않습니다. 추가 검색 결과는 미검토 후보입니다.</p><button class="button subtle" data-load-photo="${E(p.place_id)}">공개 이미지 후보 확인</button><div id="photoResult"></div></section><section><div class="section-head"><h2>나의 현장 기록</h2><button class="button subtle small" data-visit="${E(p.place_id)}">＋ 기록</button></div>${vis.length?vis.map(visitHTML).join(''):empty('첫 관찰을 남겨보세요.','빛의 움직임, 건축 외피, 관람 위치와 느낀 점을 기록하세요.')}${db.legacyVisits[p.place_id]?`<p class="muted">이전 버전 방문 횟수: ${db.legacyVisits[p.place_id]}회 · 날짜와 메모 없음</p>`:''}</section></div><aside><div class="panel"><h2>방문 전에 확인하세요</h2><dl><div class="kv"><dt>주소</dt><dd>${E(p.address||'주소 미확인')}</dd></div><div class="kv"><dt>수록 운영시간</dt><dd>${E(p.current_hours_verified||p.typical_hours||'확인 필요')}</dd></div><div class="kv"><dt>요금</dt><dd>${p.free===true?'무료로 수록':p.free===false?'유료 / 조건부로 수록':'미확인'}</dd></div><div class="kv"><dt>기존 확인일</dt><dd>${E(p.verified_at||'없음')}${f.age!==null?` · ${f.age}일 경과`:''}</dd></div><div class="kv"><dt>좌표</dt><dd>${C.coords(p)?E(C.coords(p).join(', '))+' · 외부 출처 제공':'미확인 · 주소 검색 사용'}</dd></div></dl><div class="actions"><button class="button" data-add-route="${E(p.place_id)}">＋ 답사 코스에 담기</button>${link(mapURL,'지도에서 주소 검색','button subtle')}</div></div><div class="notice warning">${E(f.label)}. 수록 정보는 현재 영업·상영을 보장하지 않습니다. 운영시간과 휴무는 공식 출처에서 확인하세요.</div><section class="panel" style="margin-top:20px"><h2>수록 프로그램</h2><p>${E(p.current_program||'현재 프로그램 미확인')}</p><p class="muted">${E(p.program_start||'')} ${p.program_end?'— '+E(p.program_end):''}</p><p class="muted">${E(p.verification_note||'')}</p><h2>원본 출처</h2>${link(official(p),'대표 출처')}${link(p.verification_source_2,'추가 확인 출처')}${src.slice(0,2).map(s=>link(s.url,s.publisher||'데이터 출처')).join('')}</section></aside></div>`}
function routesPage(){return heading('PERSONAL ITINERARIES','나의 답사 코스','장소의 순서를 정하고, 관찰할 질문을 적고, 현장으로 가져가세요.')+`<div class="actions"><button class="button" data-new-route>＋ 새 코스 만들기</button><a class="button subtle" href="#calendar">프로그램 일정 보기</a></div><div class="section-head"><h2>내가 만드는 여정</h2><span class="muted">${db.routes.length}개</span></div>${db.routes.length?`<div class="collection-grid">${db.routes.map((r,i)=>`<a class="collection" href="#route/${E(r.id)}"><span class="collection-number">${String(i+1).padStart(2,'0')} ↝</span><h3>${E(r.name)}</h3><p>${E(r.date||'날짜 미정')} · ${r.stops.length}곳</p><span class="text-link">코스 편집 →</span></a>`).join('')}</div>`:empty('다음 답사를 설계하세요.','새 코스를 만들거나, 아래 에디토리얼 코스를 복사해서 시작하세요.')}<div class="section-head"><div><h2>에디토리얼 코스</h2><small>첨부 자료의 기존 코스 · 최신 운영 여부와 동선은 확인이 필요합니다.</small></div></div><div class="collection-grid">${D.curations.map(collection).join('')}</div>`}
function curationPage(c){if(!c)return notFound();const links=D.curation_places.filter(x=>x.curation_id===c.curation_id&&place(x.place_id)).sort((a,b)=>a.order-b.order);return `<a class="text-link" href="#routes">← 답사 코스</a><div style="margin-top:25px">${heading('EDITORIAL JOURNEY',E(c.title),E(c.description))}</div><div class="actions"><button class="button" data-copy-curation="${E(c.curation_id)}">내 코스로 복사</button></div><p class="notice" style="margin-top:20px">수록 소요시간: ${E(c.estimated_time||'미정')} · 실제 이동시간을 계산한 값이 아닙니다. 아래 순서를 복사 후 자유롭게 바꿀 수 있습니다.</p><div class="list">${links.map((x,i)=>row(place(x.place_id),`${i+1}. ${x.editor_comment||''}`)).join('')}</div>`}
function routePage(r){if(!r)return notFound();return `<a class="text-link" href="#routes">← 나의 코스</a><div style="margin-top:25px">${heading('FIELDWORK PLANNER',E(r.name),`${r.stops.length}곳 · ${E(r.date||'날짜 미정')}`)}</div><form id="routeForm" data-route-id="${E(r.id)}"><div class="route-header"><input name="name" value="${E(r.name)}" maxlength="120" required aria-label="코스 이름"><input name="date" type="date" value="${E(r.date)}" aria-label="답사 날짜"><button class="button" type="submit">변경 저장</button></div><label class="field">답사 질문 / 메모<textarea name="note" maxlength="2000" placeholder="관찰할 요소, 촬영 위치, 건축과 빛의 관계…">${E(r.note)}</textarea></label></form><div class="actions" style="margin:20px 0"><button class="button subtle" data-route-picker="${E(r.id)}">＋ 장소 추가</button><button class="button subtle" data-route-ics="${E(r.id)}">일정 파일</button><button class="button subtle" data-print>인쇄 / PDF</button><button class="button subtle" data-route-copy="${E(r.id)}">코스 복제</button><button class="button danger" data-route-delete="${E(r.id)}">삭제</button></div><div class="notice" style="margin-bottom:20px">순서는 직접 편집합니다. 좌표 미확인 장소가 있어 자동 최단경로·이동시간은 제공하지 않습니다. 일정 파일은 시간 미정의 종일 일정입니다. 내보내기 전 변경 내용을 저장하세요.</div><div class="print-only"><p>${E(r.date)}</p><p class="record-note">${E(r.note)}</p></div><div class="list">${r.stops.map((pid,i)=>{const p=place(pid);return `<div class="list-row"><span class="stop-number">${String(i+1).padStart(2,'0')}</span><div class="row-main"><a href="#place/${E(pid)}"><h3>${E(p.name_kr)}</h3></a><p>${E(p.address||p.district||'주소 미확인')}</p>${badge(p)}</div><div class="actions"><button class="button subtle small" data-move="${E(r.id)}" data-index="${i}" data-direction="-1" ${i===0?'disabled':''} aria-label="${E(p.name_kr)} 위로">↑</button><button class="button subtle small" data-move="${E(r.id)}" data-index="${i}" data-direction="1" ${i===r.stops.length-1?'disabled':''} aria-label="${E(p.name_kr)} 아래로">↓</button><button class="button subtle small" data-remove-stop="${E(r.id)}" data-stop="${E(pid)}" aria-label="${E(p.name_kr)} 코스에서 제거">×</button></div></div>`}).join('')||empty('아직 장소가 없습니다.','장소 추가 버튼으로 첫 목적지를 정하세요.')}</div>`}
function savedPage(){const ps=db.saved.map(place).filter(Boolean),groups=new Map();for(const p of ps){const r=X.region(p),key=[r.country,r.city].filter(Boolean).join(' · ')||'지역 미확인';if(!groups.has(key))groups.set(key,[]);groups.get(key).push(p)}return heading('SAVED PLACES','저장한 프로젝트','마음에 남은 공간을 다음 답사로 연결하세요.')+`<div class="actions"><button class="button" data-saved-route ${ps.length?'':'disabled'}>저장 장소로 코스 만들기</button><button class="button subtle" data-export-saved ${ps.length?'':'disabled'}>CSV 내보내기</button><a href="#account" class="button subtle">동기화 상태</a></div>${ps.length?[...groups].map(([name,list])=>`<div class="section-head"><h2>${E(name)}</h2><span>${list.length}개</span></div><div class="grid">${list.map(card).join('')}</div>`).join(''):empty('아직 저장한 공간이 없습니다.','프로젝트 카드의 하트를 눌러 모아보세요.','<a class="button" href="#explore">프로젝트 발견하기</a>')}`}
function visitHTML(v){const p=place(v.placeId);return `<article class="panel"><div class="section-head" style="margin:0"><div><a href="#place/${E(v.placeId)}"><h3>${E(p?.name_kr||v.placeId)}</h3></a><small>${E(v.date)} · <span class="stars">${v.rating?'★'.repeat(v.rating):'평가 없음'}</span></small></div><div class="actions"><button class="button subtle small" data-edit-visit="${E(v.id)}">편집</button><button class="button subtle small" data-delete-visit="${E(v.id)}">삭제</button></div></div><p class="record-note">${E(v.note||'메모 없음')}</p><div class="actions"><button class="button subtle small" data-visit-photos="${E(v.id)}">개인 사진</button><button class="button subtle small" data-save="${E(v.placeId)}">${db.saved.includes(v.placeId)?'♥ 다시 볼 장소에 저장됨':'♡ 다시 볼 장소 저장'}</button></div></article>`}
function journalPage(){const visits=[...db.visits].sort((a,b)=>b.date.localeCompare(a.date));const legacy=Object.values(db.legacyVisits).reduce((a,b)=>a+b,0);return heading('OBSERVE / DOCUMENT / REFLECT','현장 기록','빛을 본 순간의 시선과 질문을 남깁니다.')+`<div class="stats-row"><div class="stat"><b>${visits.length}</b><span>방문 기록</span></div><div class="stat"><b>${new Set(visits.map(v=>v.placeId)).size}</b><span>기록한 장소</span></div><div class="stat"><b>${db.routes.length}</b><span>답사 코스</span></div><div class="stat"><b>${legacy}</b><span>이전 방문 횟수</span></div></div><div class="actions" style="margin-bottom:25px"><button class="button" data-new-visit>＋ 방문 기록</button><button class="button subtle" data-export-visits ${visits.length?'':'disabled'}>기록 CSV</button><a class="button subtle" href="#settings">백업 / 복원</a></div>${visits.map(visitHTML).join('')||empty('답사는 기록으로 남습니다.','관람 날짜와 메모를 작성해 나만의 빛 아카이브를 시작하세요.')} `}
function calendarPage(){const ps=allPlaces().filter(p=>p.content_type!=='permanent'&&(C.validDate(p.program_start)||C.validDate(p.program_end))).sort((a,b)=>(a.program_start||a.program_end).localeCompare(b.program_start||b.program_end));return heading('PLAN YOUR VISIT','빛을 만나는 일정','전시·프로그램의 수록 일정과 나의 답사 계획을 함께 확인하세요.')+`<div class="section-head"><h2>나의 답사</h2><a class="text-link" href="#routes">코스 만들기 →</a></div>${db.routes.filter(r=>r.date).map(r=>`<a class="calendar-row" href="#route/${E(r.id)}"><b>${E(r.date)}</b><span>${E(r.name)} · ${r.stops.length}곳</span></a>`).join('')||empty('아직 예정된 답사가 없습니다.','코스에 날짜를 지정하면 이곳에 표시됩니다.')}<div class="section-head"><h2>전시·기간형 프로그램</h2></div><p class="notice">아래 날짜는 수록된 일정입니다. 최신 운영 여부와 휴관일은 공식 출처에서 확인하세요.</p>${ps.map(p=>`<div class="calendar-row"><b>${E(p.program_start||'시작 미확인')}<br>${E(p.program_end||'종료 미확인')}</b><div><a href="#place/${E(p.place_id)}"><h3>${E(p.name_kr)}</h3></a><p>${E(p.current_program||'프로그램명 미확인')}</p>${link(official(p),'공식 안내')}</div>${badge(p)}</div>`).join('')||empty('확인 가능한 기간형 일정이 없습니다.','상설 장소는 행사 종료일을 임의로 부여하지 않습니다.')}`}
function settings(){const counts=D.places.reduce((a,p)=>{const k=C.freshness(p).key;a[k]=(a[k]||0)+1;return a},{});return heading('DATA & WORKSPACE','데이터 및 설정','기기 내 기록은 오프라인에서도 보관합니다. 계정을 연결하면 개인 기록을 동기화할 수 있습니다.')+`${storageBlocked?`<p class="notice warning">${E(loaded.warning)}</p>`:''}<div class="settings-grid"><section class="panel"><h2>나의 데이터</h2><a class="button subtle" href="#account">계정 및 동기화 →</a><p class="muted">백업에는 저장 장소, 코스, 방문 메모, 세계 검색 저장 후보가 포함됩니다. 복원은 현재 데이터를 교체합니다.</p><div class="actions"><button class="button" data-backup>JSON 백업</button><button class="button subtle" data-restore>백업 복원</button><button class="button danger" data-reset>기록 초기화</button></div><input id="backupInput" class="hidden" type="file" accept="application/json,.json"></section><section class="panel"><h2>앱 사용 환경</h2><p class="muted">${navigator.onLine?'현재 온라인':'현재 오프라인'} · 외부 검색·사진은 네트워크가 필요합니다. 기본 장소와 개인 기록은 첫 접속 후 오프라인 사용을 지원합니다.</p><div class="actions"><button class="button subtle" data-install>홈 화면에 설치</button><a class="button subtle" href="./admin/">서버 관리자</a></div><p class="muted" style="margin-top:16px">서버 관리자·자동 수집은 별도 Supabase 설정이 필요합니다. 계정 연결 상태는 계정 화면에서 확인할 수 있습니다.</p></section></div><section class="panel"><h2>데이터 상태</h2><p>화면용 원본: ${D.places.length}곳 · 좌표 보유 ${D.places.filter(C.coords).length}곳 · 재확인 시점 경과 ${counts.stale||0}곳</p><p class="muted">판정 기준: 서울 날짜 기준 (오늘 − 기존 확인일) ≥ refresh_days. 프로그램 종료일이 지났으면 종료를 우선 표시합니다. 권리·운영정보를 이번 버전에서 새로 검증한 것으로 표시하지 않습니다.</p><div class="actions"><button class="button subtle" data-audit-csv>검토 목록 CSV</button><a class="button subtle" href="#audit">검토 목록 보기</a></div></section><section class="panel"><h2>개인정보와 외부 서비스</h2><p class="muted">기록·코스·저장 목록은 이 브라우저의 localStorage에 보관합니다. 비회원 기록은 이 기기에만 보관합니다. 로그인하여 작성하거나 이관에 동의한 기록은 연결된 Supabase 서버로 전송됩니다. 세계 검색 시 검색어가 Wikidata에, 이미지 조회 시 장소명이 Wikimedia Commons에 전송됩니다. 외부 지도·공식 사이트는 새 창에서 열립니다. 방문 기록과 코스 메모는 외부 검색에 포함하지 않습니다.</p><p class="muted">비공개 호스팅의 접속·인증 처리는 호스팅 제공자의 정책을 따릅니다. 백업 파일에 개인 메모가 포함될 수 있으므로 공유 전에 확인하세요.</p></section>`}
function auditPage(){return heading('CONTENT REVIEW','데이터 검토 목록','원본 데이터를 수정하지 않고 갱신이 필요한 항목을 확인합니다.')+`<div class="actions"><button class="button subtle" data-audit-csv>CSV 내보내기</button></div><div class="table-scroll"><table class="audit-table"><thead><tr><th>장소</th><th>판정</th><th>기존 확인일</th><th>갱신 주기</th><th>출처</th></tr></thead><tbody>${[...D.places].sort((a,b)=>(a.verified_at||'').localeCompare(b.verified_at||'')).map(p=>`<tr><td><a href="#place/${E(p.place_id)}">${E(p.name_kr)}</a></td><td>${badge(p)}</td><td>${E(p.verified_at||'없음')}</td><td>${p.refresh_days||30}일</td><td>${link(official(p),'확인')}</td></tr>`).join('')}</tbody></table></div>`}
function notFound(){return empty('페이지를 찾을 수 없습니다.','삭제된 코스 또는 이 기기에 없는 개인 기록일 수 있습니다.','<a class="button" href="#home">홈으로</a>')}
function render(){const wasMap=typeof currentMap!=='undefined'&&!!currentMap;if(typeof currentMap!=='undefined'&&currentMap){currentMap.remove();currentMap=null;mapMarkers=[]}document.documentElement?.setAttribute('data-theme',db.preferences?.theme||'light');const [page,id]=pagePath();const active=['place','audit','magazine','article'].includes(page)?'explore':['route','routes','curation','calendar','account','settings','journal'].includes(page)?'my':page;$('#navigation').innerHTML=navItems.map(([key,icon,title])=>`<a class="nav-link ${key===active?'active':''}" href="#${key}" ${key===active?'aria-current="page"':''}><span aria-hidden="true">${icon}</span>${title}${key==='saved'?`<b class="nav-count">${db.saved.length}</b>`:''}</a>`).join('');let html;switch(page){case 'my':html=myPage();break;case 'magazine':html=heading('LIGHT JOURNAL','빛의 건축 읽기')+(articles().length?magazineCards():empty('등록된 글이 없습니다.','공개 승인된 해설과 연구 콘텐츠가 이곳에 표시됩니다.'));break;case 'article':html=articlePage(id);break;case 'home':html=home();break;case 'explore':html=explore();break;case 'map':html=mapPage();break;case 'place':html=detail(place(id));break;case 'routes':html=routesPage();break;case 'route':html=routePage(route(id));break;case 'curation':html=curationPage(D.curations.find(c=>c.curation_id===id));break;case 'saved':html=savedPage();break;case 'journal':html=journalPage();break;case 'calendar':html=calendarPage();break;case 'account':html=window.AOLAccount?window.AOLAccount.page():heading('ACCOUNT','계정 연결 준비 중','잠시 후 다시 열어주세요.');break;case 'settings':html=settings();break;case 'audit':html=auditPage();break;default:html=notFound()}$('#view').innerHTML=html;document.title=($('#view h1')?.textContent||'도시의 빛')+' · 빛의 건축';bindPage();if(page==='account')window.AOLAccount?.bind();if(page==='map'&&wasMap)loadMap()}
function modal(title,content){const el=$('#modal');el.innerHTML=`<div class="modal-head"><h2 id="modalTitle">${E(title)}</h2><button class="button subtle small" data-close aria-label="닫기">×</button></div>${content}`;if(!el.open)el.showModal();el.querySelector('[data-close]').onclick=()=>el.close();return el}
function confirmAction(title,text,fn){const el=modal(title,`<p>${E(text)}</p><div class="form-actions"><button class="button subtle" id="cancelConfirm">취소</button><button class="button danger" id="yesConfirm">확인</button></div>`);$('#cancelConfirm').onclick=()=>el.close();$('#yesConfirm').onclick=()=>{el.close();fn()}}
function newRoute(stops=[],name='나의 빛 답사'){const el=modal('새 답사 코스',`<form id="newRouteForm" class="form-grid"><label class="field">코스 이름<input name="name" value="${E(name)}" maxlength="120" required></label><label class="field">답사 날짜 (선택)<input type="date" name="date"></label><div class="form-actions"><button class="button" type="submit">코스 만들기</button></div></form>`);$('#newRouteForm').onsubmit=e=>{e.preventDefault();const fd=new FormData(e.target),r={id:C.id(),name:fd.get('name').trim(),date:fd.get('date'),note:'',stops:[...new Set(stops)].slice(0,50)};if(!r.name)return;if(change(d=>d.routes.push(r))){el.close();go('route/'+r.id);toast('답사 코스를 만들었습니다.')}}}
function addToRoute(pid){if(!db.routes.length){newRoute([pid]);return}const el=modal('어느 코스에 담을까요?',`<div class="list">${db.routes.map(r=>`<button class="button subtle" data-select-route="${E(r.id)}" ${r.stops.includes(pid)?'disabled':''}>${E(r.name)} · ${r.stops.length}곳 ${r.stops.includes(pid)?'· 이미 포함':''}</button>`).join('')}</div><div class="form-actions"><button class="button" id="newRouteForPlace">＋ 새 코스</button></div>`);el.querySelectorAll('[data-select-route]').forEach(b=>b.onclick=()=>{const r=route(b.dataset.selectRoute);if(r.stops.length>=50){toast('한 코스에는 최대 50곳을 담을 수 있습니다.');return}if(change(d=>d.routes.find(x=>x.id===r.id).stops.push(pid))){el.close();toast('코스에 담았습니다.')}});$('#newRouteForPlace').onclick=()=>newRoute([pid])}
function routePicker(rid){const el=modal('코스에 장소 추가',`<input id="pickerSearch" placeholder="장소 이름 검색" aria-label="추가할 장소 검색" style="width:100%;margin-bottom:15px"><div id="pickerResults" class="list"></div>`);function draw(){const r=route(rid),q=$('#pickerSearch').value;$('#pickerResults').innerHTML=C.filterPlaces(allPlaces(),{q}).slice(0,30).map(p=>`<button class="button subtle" data-pick="${E(p.place_id)}" ${r.stops.includes(p.place_id)?'disabled':''}>${E(p.name_kr)} ${r.stops.includes(p.place_id)?'· 추가됨':'＋'}</button>`).join('');el.querySelectorAll('[data-pick]').forEach(b=>b.onclick=()=>{if(r.stops.length>=50){toast('한 코스에는 최대 50곳까지 담을 수 있습니다.');return}if(change(d=>d.routes.find(x=>x.id===rid).stops.push(b.dataset.pick))){draw();render();toast('장소를 추가했습니다.')}})}$('#pickerSearch').oninput=draw;draw()}
function visitForm(pid='',visitId=''){const v=db.visits.find(x=>x.id===visitId)||{placeId:pid,date:C.today(),rating:0,note:''};const el=modal(visitId?'방문 기록 편집':'새 방문 기록',`<form id="visitForm" class="form-grid"><label class="field">장소<select name="placeId" required><option value="">장소 선택</option>${allPlaces().map(p=>`<option value="${E(p.place_id)}" ${v.placeId===p.place_id?'selected':''}>${E(p.name_kr)}</option>`).join('')}</select></label><label class="field">방문 날짜<input type="date" name="date" required max="${C.today()}" value="${E(v.date)}"></label><label class="field">나의 평가<select name="rating">${[0,1,2,3,4,5].map(n=>`<option value="${n}" ${v.rating===n?'selected':''}>${n?'★'.repeat(n):'평가 없음'}</option>`).join('')}</select></label><label class="field">현장 메모<textarea name="note" maxlength="4000" placeholder="건축 외피와 빛의 관계, 시야, 밝기, 소리, 머무는 방식…">${E(v.note)}</textarea></label><div class="form-actions"><button class="button" type="submit">기록 저장</button></div></form>`);$('#visitForm').onsubmit=e=>{e.preventDefault();const f=new FormData(e.target),item={id:visitId||C.id(),placeId:f.get('placeId'),date:f.get('date'),rating:Number(f.get('rating')),note:f.get('note')};if(!place(item.placeId)||!C.validDate(item.date)||item.date>C.today()){toast('장소와 방문 날짜를 확인하세요.');return}if(change(d=>{if(visitId)d.visits=d.visits.map(x=>x.id===visitId?item:x);else d.visits.push(item)})){el.close();render();toast('현장 기록을 저장했습니다.')}}}
function download(name,content,type){const url=URL.createObjectURL(new Blob([content],{type})),a=document.createElement('a');a.href=url;a.download=name;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),2000)}
function backup(){download('빛의건축_백업_'+C.today()+'.json',JSON.stringify({...db,exportedAt:new Date().toISOString()},null,2),'application/json')}
function exportSaved(){download('빛의건축_저장장소.csv',C.csv([['장소','지역','주소','출처'],...db.saved.map(place).filter(Boolean).map(p=>[p.name_kr,p.district,p.address,official(p)])]),'text/csv;charset=utf-8')}
function exportVisits(){download('빛의건축_방문기록.csv',C.csv([['날짜','장소','평가','메모'],...db.visits.map(v=>[v.date,place(v.placeId)?.name_kr,v.rating,v.note])]),'text/csv;charset=utf-8')}
function auditCSV(){download('빛의건축_갱신검토.csv',C.csv([['ID','장소','판정','기존 확인일','갱신주기(일)','좌표 상태','출처'],...D.places.map(p=>[p.place_id,p.name_kr,C.freshness(p).label,p.verified_at,p.refresh_days,C.coords(p)?'있음':'미확인',official(p)])]),'text/csv;charset=utf-8')}
async function importFile(file){if(!file)return;if(file.size>5*1024*1024){toast('백업 파일은 5MB 이하여야 합니다.');return}try{const next=C.validate(JSON.parse(await file.text()),D.places.map(p=>p.place_id));confirmAction('백업으로 복원할까요?',`현재 기록을 저장 ${next.saved.length}곳, 코스 ${next.routes.length}개, 방문 ${next.visits.length}개로 교체합니다. 필요하면 먼저 현재 데이터를 백업하세요.`,()=>{if(!C.write(storage,next)){toast('저장에 실패했습니다. 현재 기록은 유지됩니다.');return}storageBlocked=false;db=next;render();toast('백업을 복원했습니다.')})}catch(e){toast('복원 실패: '+e.message)}}
async function fetchJSON(url){const controller=new AbortController(),timer=setTimeout(()=>controller.abort(),12000);try{const r=await fetch(url,{signal:controller.signal,credentials:'omit'});if(!r.ok)throw Error('HTTP '+r.status);return await r.json()}finally{clearTimeout(timer)}}
async function searchGlobal(){const q=($('#globalSearch')?.value||globalQuery).trim();if(!q){toast('검색어를 입력하세요.');return}const seq=++searchSeq;globalQuery=q;globalBusy=true;globalError='';globalResults=[];render();try{const lang=/[가-힣]/.test(q)?'ko':'en';const s=await fetchJSON('https://www.wikidata.org/w/api.php?action=wbsearchentities&format=json&origin=*&language='+lang+'&uselang=ko&limit=12&search='+encodeURIComponent(q));const ids=(s.search||[]).map(x=>x.id).filter(x=>/^Q\d+$/.test(x));if(!ids.length){globalError='검색 결과가 없습니다. 다른 이름이나 영문명으로 검색해보세요.';return}const data=await fetchJSON('https://www.wikidata.org/w/api.php?action=wbgetentities&format=json&origin=*&props=labels|descriptions|claims&languages=ko|en&ids='+ids.join('|'));if(seq!==searchSeq)return;const claim=(e,k)=>e.claims?.[k]?.[0]?.mainsnak?.datavalue?.value;globalResults=ids.map(id=>{const e=data.entities?.[id];if(!e)return null;const coord=claim(e,'P625');return {place_id:'WD-'+id,name_kr:e.labels?.ko?.value||e.labels?.en?.value||id,name_en:e.labels?.en?.value||'',short_description:e.descriptions?.ko?.value||e.descriptions?.en?.value||'',primary_category:'Global',district:'세계 검색',origin:'wikidata',latitude:coord?.latitude??null,longitude:coord?.longitude??null,website:C.safeURL(claim(e,'P856')),source_url:'https://www.wikidata.org/wiki/'+id,image:claim(e,'P18')||'',verified_at:''}}).filter(Boolean)}catch(e){if(seq===searchSeq)globalError=navigator.onLine?'외부 검색에 실패했습니다. 잠시 후 다시 시도하세요.':'오프라인에서는 세계 검색을 사용할 수 없습니다.'}finally{if(seq===searchSeq){globalBusy=false;if(pagePath()[0]==='explore')render()}}}
async function loadPhoto(pid){const p=place(pid),box=$('#photoResult');if(!box)return;box.innerHTML='<p class="loading" role="status">이미지 메타데이터 확인 중…</p>';const strip=x=>{const doc=new DOMParser().parseFromString(String(x||''),'text/html');return doc.body.textContent||''};try{const params=p.image?'titles='+encodeURIComponent('File:'+p.image):'generator=search&gsrnamespace=6&gsrlimit=3&gsrsearch='+encodeURIComponent(p.name_en||p.name_kr);const data=await fetchJSON('https://commons.wikimedia.org/w/api.php?action=query&format=json&origin=*&prop=imageinfo&iiprop=url|extmetadata&iiurlwidth=1000&'+params);const records=Object.values(data.query?.pages||{}).map(pg=>{const i=pg.imageinfo?.[0],m=i?.extmetadata||{},license=strip(m.LicenseShortName?.value||m.UsageTerms?.value);return {title:pg.title,url:C.safeURL(i?.thumburl||i?.url),license,artist:strip(m.Artist?.value||m.Credit?.value),licenseURL:C.safeURL(m.LicenseUrl?.value),source:'https://commons.wikimedia.org/wiki/'+encodeURIComponent(pg.title||'')}}).filter(a=>a.url&&/^(CC BY(?:-SA)? [\d.]+|CC0(?: [\d.]+)?|Public domain)$/i.test(a.license));if(!box.isConnected)return;box.innerHTML=records.length?records.map(a=>`<figure style="margin:20px 0"><img class="photo" src="${E(a.url)}" alt="${E(a.title)} · 자동 검색 후보" loading="lazy" referrerpolicy="no-referrer"><figcaption class="photo-credit">${E(a.artist||'작성자 표기 확인 필요')} · ${E(a.license)}${link(a.source,'원본·장소 일치 여부 확인')}${link(a.licenseURL,'라이선스 조건')}</figcaption></figure>`).join('')+'<p class="notice">메타데이터 조건으로 선별한 자동 후보입니다. 사진 속 장소 일치와 개별 사용조건을 원본에서 확인하세요.</p>':'<p class="notice">자동 표시 조건에 맞는 이미지가 없습니다. 기본 그래픽을 유지합니다.</p>'}catch{if(box.isConnected)box.innerHTML='<p class="notice warning">이미지를 가져오지 못했습니다. 다시 시도하거나 공식 출처를 확인하세요.</p>'}}
function bindPage(){const handle=$('#mapHandle');if(handle){const resize=y=>{const el=$('#mapExplorer');if(el)el.style.setProperty('--sheet-height',Math.max(100,Math.min(window.innerHeight*.75,window.innerHeight-y-80))+'px')};handle.onpointerdown=e=>{handle.setPointerCapture(e.pointerId);handle.onpointermove=m=>resize(m.clientY)};handle.onpointerup=()=>handle.onpointermove=null;handle.onkeydown=e=>{if(['ArrowUp','ArrowDown'].includes(e.key)){e.preventDefault();const panel=handle.parentElement;$('#mapExplorer').style.setProperty('--sheet-height',Math.max(100,panel.clientHeight+(e.key==='ArrowUp'?40:-40))+'px')}};}const hs=$('#homeSearch');if(hs)hs.onsubmit=e=>{e.preventDefault();filters={q:String(new FormData(hs).get('q')||''),category:'전체'};go('explore')};document.querySelectorAll?.('[data-search-filter]').forEach(el=>el.onchange=()=>{filters[el.dataset.searchFilter]=el.value;if(el.dataset.searchFilter==='country')filters.city='';showCount=18;render()});const input=$('#placeSearch');if(input)input.oninput=()=>{filters.q=input.value;showCount=18;if(pagePath()[0]==='map')updateMapResults();else $('#placeResults').innerHTML=resultsHTML()};const district=$('#districtFilter');if(district)district.onchange=()=>{filters.district=district.value;showCount=18;render()};const gs=$('#globalSearch');if(gs)gs.onkeydown=e=>{if(e.key==='Enter')searchGlobal()};const gb=$('#globalSearchButton');if(gb)gb.onclick=searchGlobal;const rf=$('#routeForm');if(rf)rf.onsubmit=e=>{e.preventDefault();const fd=new FormData(rf),name=fd.get('name').trim(),date=fd.get('date');if(!name||date&&!C.validDate(date))return;if(change(d=>Object.assign(d.routes.find(x=>x.id===rf.dataset.routeId),{name,date,note:fd.get('note')}))){render();toast('코스 변경을 저장했습니다.')}};const bi=$('#backupInput');if(bi)bi.onchange=()=>importFile(bi.files[0])}
document.addEventListener('click',async e=>{const b=e.target.closest('button');if(!b||b.disabled)return;const d=b.dataset;
 if(d.discoverCategory){filters={q:'',category:d.discoverCategory};go('explore')}
 else if(d.cityLink){filters={q:'',category:'전체',city:d.cityLink};go('explore')}
 else if('theme'in d){if(change(x=>x.preferences.theme=x.preferences.theme==='dark'?'light':'dark'))render()}
 else if(d.save){if(change(x=>{x.saved=x.saved.includes(d.save)?x.saved.filter(id=>id!==d.save):[...x.saved,d.save]})){render();toast(db.saved.includes(d.save)?'장소를 저장했습니다.':'저장을 해제했습니다.')}}
 else if(d.category){filters.category=d.category;showCount=18;render()}
 else if(d.filterToggle){filters[d.filterToggle]=!filters[d.filterToggle];showCount=18;render()}
 else if('resetFilter'in d){filters={q:'',category:'전체',district:'전체',free:false,indoor:false};showCount=18;render()}
 else if('more'in d){showCount+=18;if(pagePath()[0]==='map')updateMapResults();else $('#placeResults').innerHTML=resultsHTML()}
 else if(d.addRoute)addToRoute(d.addRoute);
 else if('newRoute'in d)newRoute();
 else if('savedRoute'in d)newRoute(db.saved,'저장한 빛의 장소');
 else if(d.copyCuration){const c=D.curations.find(x=>x.curation_id===d.copyCuration);newRoute(D.curation_places.filter(x=>x.curation_id===c.curation_id&&place(x.place_id)).sort((a,b)=>a.order-b.order).map(x=>x.place_id),c.title)}
 else if(d.routePicker)routePicker(d.routePicker);
 else if(d.move){if(change(x=>{const stops=x.routes.find(r=>r.id===d.move).stops,i=Number(d.index),j=i+Number(d.direction);if(j>=0&&j<stops.length)[stops[i],stops[j]]=[stops[j],stops[i]]}))render()}
 else if(d.removeStop){if(change(x=>{const r=x.routes.find(r=>r.id===d.removeStop);r.stops=r.stops.filter(id=>id!==d.stop)}))render()}
 else if(d.routeDelete)confirmAction('코스 삭제','이 코스를 삭제할까요? 방문 기록과 저장 장소는 유지됩니다.',()=>{if(change(x=>x.routes=x.routes.filter(r=>r.id!==d.routeDelete)))go('routes')});
 else if(d.routeCopy){const old=route(d.routeCopy),copy={...old,id:C.id(),name:old.name.slice(0,113)+' (복사)',stops:[...old.stops]};if(change(x=>x.routes.push(copy)))go('route/'+copy.id)}
 else if(d.routeIcs){try{download('빛의건축_답사일정.ics',C.ics(route(d.routeIcs),place),'text/calendar;charset=utf-8')}catch(err){toast(err.message)}}
 else if('print'in d)window.print();
 else if(d.visit)visitForm(d.visit);
 else if('newVisit'in d)visitForm();
 else if(d.visitPhotos)privatePhotos(d.visitPhotos);
 else if(d.editVisit)visitForm('',d.editVisit);
 else if(d.deleteVisit)confirmAction('방문 기록 삭제','이 기록을 삭제할까요?',async()=>{try{if(window.AOLCloud?.state.user){const photos=await window.AOLCloud.photos.list(d.deleteVisit);for(const photo of photos)await window.AOLCloud.photos.remove(photo.id)}if(change(x=>x.visits=x.visits.filter(v=>v.id!==d.deleteVisit)))render()}catch(err){toast('사진 삭제를 완료하지 못해 기록을 유지했습니다. '+err.message)}});
 else if(d.share){const url=new URL(location.href);url.hash='place/'+d.share;try{await (window.AOLNative?.share(url.href,place(d.share)?.name_kr)||navigator.clipboard.writeText(url.href));toast('공유 요청을 처리했습니다.')}catch{modal('장소 링크',`<p class="muted">복사해서 사용하세요. 링크를 열어 장소를 확인할 수 있습니다.</p><input value="${E(url.href)}" readonly style="width:100%" aria-label="장소 링크">`)}}
 else if('backup'in d)backup();
 else if('restore'in d)$('#backupInput').click();
 else if('reset'in d)confirmAction('모든 개인 기록 초기화','현재 브라우저의 저장 장소·코스·방문 기록을 삭제합니다. 먼저 백업을 권장합니다.',()=>{const next=C.empty();storageBlocked=false;if(!commit(next)){toast('초기화에 실패했습니다.');return}render();toast('현재 버전의 개인 기록을 초기화했습니다.')});
 else if('exportSaved'in d)exportSaved();
 else if('exportVisits'in d)exportVisits();
 else if('auditCsv'in d)auditCSV();
 else if(d.globalSave){const p=globalResults.find(x=>x.place_id===d.globalSave);if(!p)return;if(change(x=>{if(!x.candidates.some(c=>c.place_id===p.place_id))x.candidates.push(p);if(!x.saved.includes(p.place_id))x.saved.push(p.place_id)})){render();toast('세계 검색 후보를 저장했습니다.')}}
 else if('retryGlobal'in d)searchGlobal();
 else if(d.loadPhoto)loadPhoto(d.loadPhoto);
 else if(d.mapMode){$('#mapExplorer').dataset.mode=d.mapMode;setTimeout(()=>currentMap?.invalidateSize(),0)}
 else if(d.mapSelect){const m=mapMarkers.find(x=>x.aolId===d.mapSelect);if(m){currentMap.panTo(m.getLatLng());m.openPopup();m.setZIndexOffset(1000)}else go('place/'+d.mapSelect)}
 else if('loadMap'in d)loadMap();
 else if('nearby'in d){try{if(!window.AOLNative)throw Error('위치 기능을 준비 중입니다.');const c=await window.AOLNative.locate();const ps=mapProjects();if(currentMap)currentMap.setView([c.latitude,c.longitude],13);if(!ps.length){toast('좌표가 확인된 장소가 없습니다. 지역명으로 검색하세요.');return}const dist=p=>{const rad=x=>x*Math.PI/180,dl=rad(p.latitude-c.latitude),dn=rad(p.longitude-c.longitude),a=Math.sin(dl/2)**2+Math.cos(rad(c.latitude))*Math.cos(rad(p.latitude))*Math.sin(dn/2)**2;return 6371*2*Math.atan2(Math.sqrt(a),Math.sqrt(1-a))};ps.sort((a,b)=>dist(a)-dist(b));$('#mapMessage').innerHTML='<h2>가까운 좌표 보유 장소</h2>'+ps.slice(0,10).map(p=>'<p>'+link(location.origin+location.pathname+'#place/'+p.place_id,p.name_kr)+' · 직선 '+dist(p).toFixed(1)+'km</p>').join('')}catch{toast('위치를 확인하지 못했습니다. 장소 탐색에서 지역명을 검색하세요.')}}
 else if('install'in d){if(installPrompt){await installPrompt.prompt();installPrompt=null}else toast('브라우저 메뉴의 ‘앱 설치’ 또는 ‘홈 화면에 추가’를 사용하세요.')}
});
$('#quickSearch').onclick=()=>{go('explore');setTimeout(()=>$('#placeSearch')?.focus(),30)};
window.addEventListener('hashchange',()=>{render();window.scrollTo(0,0);$('#view').focus({preventScroll:true})});
window.addEventListener('storage',e=>{if(e.key===(activeUser?'aol12_user_'+activeUser:C.KEY)&&e.newValue){try{db=C.validate(JSON.parse(e.newValue),D.places.map(p=>p.place_id));storageBlocked=false;render();toast('다른 탭의 변경 사항을 반영했습니다.')}catch{toast('다른 탭의 데이터 형식을 읽을 수 없습니다.')}}});
function network(){$('#networkStatus').textContent=navigator.onLine?'● ONLINE':'○ OFFLINE'}window.addEventListener('online',network);window.addEventListener('offline',network);
window.addEventListener('beforeinstallprompt',e=>{e.preventDefault();installPrompt=e});
render();network();if(loaded.warning)toast(loaded.warning);
if('serviceWorker'in navigator&&location.protocol.startsWith('http')&&!window.Capacitor?.isNativePlatform?.())navigator.serviceWorker.register('./sw.js').catch(()=>{});

function mapPage(){return heading('SPATIAL EXPLORER','지도에서 만나는 빛','검증된 좌표가 있는 프로젝트만 표시합니다.')+filterHTML()+`<div class="map-controls"><a class="button subtle" href="#explore">같은 조건으로 목록 보기</a><button class="button subtle" data-nearby>내 위치</button><button class="button subtle map-toggle" data-map-mode="map">지도만</button><button class="button subtle map-toggle" data-map-mode="list">목록만</button><button class="button subtle map-toggle" data-map-mode="both">함께 보기</button></div><div id="mapMessage" role="status"></div><div class="map-explorer" id="mapExplorer" data-mode="both"><div class="map-list"><button class="map-handle" id="mapHandle" aria-label="프로젝트 목록 높이 조절, 위아래 방향키 사용">━━</button><div id="mapResults">${mapResultHTML()}</div></div><div class="map-stage"><div id="mapCanvas" class="map-placeholder"><div><h2>좌표가 확인된 공간을 찾아보세요</h2><p class="muted">지도 표시 시 외부 지도 공급자에 연결합니다.</p><button class="button" data-load-map>지도 불러오기</button></div></div></div></div>`}
let mapLibraryPromise=null;var currentMap=null,mapMarkers=[];
async function loadMap(){const box=$('#mapCanvas'),message=$('#mapMessage');if(!box)return;message.textContent='지도를 불러오는 중…';try{if(!window.L){if(!mapLibraryPromise)mapLibraryPromise=new Promise((resolve,reject)=>{const css=document.createElement('link');css.rel='stylesheet';css.href='./assets/vendor/leaflet/leaflet.css';document.head.appendChild(css);const script=document.createElement('script');script.src='./assets/vendor/leaflet/leaflet.js';const timer=setTimeout(()=>reject(Error('timeout')),12000);script.onload=()=>{clearTimeout(timer);resolve()};script.onerror=()=>{clearTimeout(timer);reject(Error('network'))};document.head.appendChild(script)});await mapLibraryPromise}if(!box.isConnected)return;box.innerHTML='';box.className='map-loaded';currentMap=L.map(box).setView([37.5665,126.978],10);L.tileLayer(window.AOL_CONFIG?.TILE_URL||'https://tile.openstreetmap.org/{z}/{x}/{y}.png',{maxZoom:19,attribution:'© <a href="https://www.openstreetmap.org/copyright">OpenStreetMap contributors</a>'}).addTo(currentMap);updateMapResults();if(mapMarkers.length)currentMap.fitBounds(L.featureGroup(mapMarkers).getBounds().pad(.2),{maxZoom:15});currentMap.on('moveend',()=>{const target=$('#mapResults');if(target)target.innerHTML=mapResultHTML(currentMap.getBounds())});message.textContent='현재 지도 영역과 프로젝트 목록이 함께 갱신됩니다.'}catch{mapLibraryPromise=null;message.textContent='지도를 불러오지 못했습니다. 프로젝트 목록과 상세의 외부 지도 링크를 이용하세요.'}}

// Account-isolated storage: never upload the guest workspace without consent.
let activeUser=null;
const rawStorage=storage;
const scopedStorage={getItem(k){return rawStorage.getItem(k===C.KEY&&activeUser?'aol12_user_'+activeUser:k)},setItem(k,v){return rawStorage.setItem(k===C.KEY&&activeUser?'aol12_user_'+activeUser:k,v)}};
storage=scopedStorage;
window.AOLApp={getDB:()=>db,backup,render,toast,
 switchUser(uid){if($('#modal')?.open)$('#modal').close();activeUser=uid;try{const raw=rawStorage.getItem(uid?'aol12_user_'+uid:C.KEY);db=raw?C.validate(JSON.parse(raw),D.places.map(p=>p.place_id)):C.empty();storageBlocked=false}catch{db=C.empty();storageBlocked=true;toast('계정 기록을 읽지 못했습니다. 원본은 보존됩니다.')}render()},
 replaceCloud(doc){const next=C.validate(doc,D.places.map(p=>p.place_id));if(!C.write(storage,next))throw Error('기기 저장에 실패했습니다.');db=next;storageBlocked=false;render()},
 mergeGuest(){const guest=C.read(rawStorage,D.places.map(p=>p.place_id));if(guest.blocked)throw Error(guest.warning);const g=guest.data;change(d=>{d.saved=[...new Set([...d.saved,...g.saved])];for(const k of ['visits','routes']){const ids=new Set(d[k].map(x=>x.id));d[k].push(...g[k].filter(x=>!ids.has(x.id)))}const ids=new Set(d.candidates.map(x=>x.place_id));d.candidates.push(...g.candidates.filter(x=>!ids.has(x.place_id)));d.legacyVisits={...g.legacyVisits,...d.legacyVisits}});render()},
 setCatalog(rows){D.places.forEach(p=>p.is_published=false);for(const row of rows){const id=row.place_code||row.id,index=D.places.findIndex(p=>p.place_id===id);const p={...(index>=0?D.places[index]:{}),...row,place_id:id,latitude:row.coordinate_review_status==='verified'?row.latitude:null,longitude:row.coordinate_review_status==='verified'?row.longitude:null,district:row.cities?.name_local||row.cities?.name_en||row.district||'',country:row.cities?.countries?.name_en||'',verified_at:row.verified_at?.slice(0,10)||''};if(index>=0)D.places[index]=p;else D.places.push(p)}try{rawStorage.setItem('aol12_public_catalog',JSON.stringify(D.places))}catch{}render()},
 setMedia(rows){window.AOL_MEDIA=rows;render()}
};

document.addEventListener('error',e=>{if(e.target?.matches?.('[data-place-photo]')){const original=e.target.dataset.original;if(original&&e.target.src!==original){delete e.target.dataset.original;e.target.src=original;return}const box=e.target.parentElement;box.innerHTML='<span class="art-label">사진을 불러오지 못했습니다 · 공식 출처를 확인하세요</span>'}},true);

function sectionCards(title,sub,ps){return `<section><div class="section-head"><div><h2>${E(title)}</h2><small>${E(sub)}</small></div><a class="text-link" href="#explore">전체 보기 →</a></div><div class="grid">${ps.map(card).join('')}</div></section>`}

function mediaURL(m){return C.safeURL(m.cached_public_url||m.display_url)}
function mediaFor(p){
 // After a successful server snapshot, absence must not resurrect revoked seed media.
 const rows=window.AOL_MEDIA===undefined?(window.AOL_REVIEWED_MEDIA||[]):window.AOL_MEDIA;
 return rows.filter(x=>x.place_code===p.place_id&&!x.review_required&&(!x.clearance_status||x.clearance_status==='cleared')&&mediaURL(x));
}

function myPage(){return heading('MY LIGHT ARCHIVE','나의 빛 아카이브','발견한 공간을 계획하고, 방문한 순간을 기록하세요.')+`<div class="my-grid">${[['saved','♡','저장한 프로젝트',db.saved.length+'개'],['routes','↝','나의 답사 코스',db.routes.length+'개'],['calendar','▦','나의 일정','전시·답사 캘린더'],['journal','▤','현장 기록',db.visits.length+'개'],['account','◉','계정과 동기화',window.AOLCloud?.state.user?'로그인됨':'비회원 모드'],['settings','⚙','데이터 및 설정','백업·복원·화면 설정']].map(([url,icon,title,n])=>`<a class="panel my-card" href="#${url}"><span>${icon}</span><h2>${title}</h2><p>${E(n)}</p></a>`).join('')}</div>`}

function articles(){return (window.AOL_ARTICLES||[]).filter(a=>a.status==='published'&&a.title&&a.body)}

function magazineCards(){return '<div class="collection-grid">'+articles().map(a=>`<a class="collection" href="#article/${E(a.id)}"><small>${E(a.author||'')} · ${E(a.published_at?.slice(0,10)||'')}</small><h3>${E(a.title)}</h3><p>${E(a.summary||'')}</p></a>`).join('')+'</div>'}

function articlePage(id){const a=articles().find(x=>x.id===id);return a?heading('LIGHT JOURNAL',E(a.title),E(a.author||''))+`<article class="panel record-note">${E(a.body)}</article>${link(a.source_url,'출처')}`:notFound()}

function detail(p){if(!p)return notFound();const meta=[['국가·도시',[X.region(p).country,X.region(p).city].filter(Boolean).join(' · ')],['건축가',p.architect],['작가',p.artist],['제작사',p.producer],['제작·개최 연도',p.project_year],['설치 장소·공간',p.spatial_context],['기술·매체',p.technology],['콘텐츠 유형',p.content_type==='permanent'?'상설':p.content_type==='temporary'?'기간형':'']];let html=detailLegacy(p);const research=`<details class="panel research-details"><summary>프로젝트 상세정보</summary><dl>${meta.map(([k,v])=>`<div class="kv"><dt>${E(k)}</dt><dd>${E(v||'정보 미등록')}</dd></div>`).join('')}</dl></details>`;html=html.replace('<section class="panel"><h2>빛의 건축 해설</h2>',research+'<section class="panel"><h2>빛의 건축 해설</h2>');const gallery=mediaFor(p);html=html.replace('<div id="photoResult"></div>',`<div class="image-gallery">${gallery.map(m=>`<figure><a href="${E(mediaURL(m))}" target="_blank" rel="noopener noreferrer"><img class="photo" src="${E(mediaURL(m))}" alt="${E(p.name_kr)}" loading="lazy" data-place-photo data-original="${E(C.safeURL(m.original_file_url))}"></a><figcaption>${E(m.creator||'')} · ${E(m.license_code||'')} ${E(m.captured_at||'')} · ${E(m.caption||'장소 사진')} · ${E(m.changes||'')} · 권리 확인 ${E((m.last_rights_sync_at||'').slice(0,10))} ${link(m.source_url,'이미지 원본')}${link(m.license_url,'사용조건')}</figcaption></figure>`).join('')}</div><div id="photoResult"></div>`);const related=allPlaces().filter(x=>x.place_id!==p.place_id&&x.primary_category===p.primary_category).slice(0,3);return html+(related.length?sectionCards('같은 유형의 프로젝트','프로젝트 유형을 기준으로 연결했습니다.',related):'')}

function mapProjects(){return X.search(allPlaces(),filters,C.today()).filter(X.mappable)}

function mapResultHTML(bounds){const all=mapProjects(),ps=bounds?all.filter(p=>bounds.contains([p.latitude,p.longitude])):all;return `<p class="result-meta">검증 좌표 ${all.length}곳 · 현재 영역 ${ps.length}곳</p>${ps.map(p=>`<button class="map-list-item" data-map-select="${E(p.place_id)}"><b>${E(p.name_kr)}</b><small>${E([X.region(p).country,X.region(p).city].filter(Boolean).join(' · '))}</small><small>${E(category(p))}</small></button>`).join('')||empty('이 영역에 검증된 장소가 없습니다.','지도 범위를 넓히거나 필터를 변경하세요. 미검증 좌표는 표시하지 않습니다.')}`}

function updateMapResults(){const el=$('#mapResults');if(!el)return;el.innerHTML=mapResultHTML(currentMap?.getBounds());if(currentMap){mapMarkers.forEach(m=>m.remove());mapMarkers=[];for(const p of mapProjects()){const m=L.marker([p.latitude,p.longitude]).addTo(currentMap).bindPopup(`<a href="#place/${E(p.place_id)}">${E(p.name_kr)} 상세 보기 →</a>`);m.aolId=p.place_id;mapMarkers.push(m)}}}

async function privatePhotos(visitId){if(!window.AOLCloud?.state.user){toast('개인 사진은 로그인 및 서버 연결 후 사용할 수 있습니다.');return}const uid=window.AOLCloud.state.user.id,el=modal('나만의 현장 사진',`<p class="muted">사진은 비공개 저장소에 보관합니다. 업로드 전에 촬영 메타데이터를 제외하고 긴 변 2,048px 이하 JPEG로 변환합니다. JPG·PNG·WebP, 파일당 5MB 이하. JSON 백업에는 사진 파일이 포함되지 않습니다.</p><input id="privatePhotoInput" type="file" accept="image/jpeg,image/png,image/webp" aria-label="개인 사진 선택"><div id="privatePhotoStatus" role="status"></div><div id="privatePhotoList"></div>`);const status=$('#privatePhotoStatus'),list=$('#privatePhotoList');const show=async()=>{const rows=await window.AOLCloud.photos.list(visitId);if(!el.open||window.AOLCloud.state.user?.id!==uid)return;list.innerHTML=rows.map(p=>`<figure><img class="photo" src="${E(C.safeURL(p.url))}" alt="나의 방문 사진"><button class="button danger small" data-private-delete="${E(p.id)}">사진 삭제</button></figure>`).join('')||'<p>첨부한 사진이 없습니다.</p>';list.querySelectorAll('[data-private-delete]').forEach(b=>b.onclick=async()=>{if(!confirm('이 사진을 영구 삭제할까요?'))return;try{await window.AOLCloud.photos.remove(b.dataset.privateDelete);await show()}catch(e){status.textContent=e.message}})};$('#privatePhotoInput').onchange=async e=>{const file=e.target.files[0];if(!file)return;status.textContent='사진 저장 중…';try{await window.AOLCloud.photos.upload(visitId,file);await show();status.textContent='저장했습니다.'}catch(e){status.textContent=e.message}e.target.value=''};try{await show()}catch(e){status.textContent=e.message}}
